/* @autogenerated */
import { Injectable } from '@angular/core';
import { TranslocoMissingHandler, TranslocoMissingHandlerData } from '@jsverse/transloco';
import { rootLogger } from '@shared/context/observability/logger.service';

// Segmentos que solo indican el papel del texto (`filter.button`, `allow-all-scopes.title`): no describen nada
const GENERIC_SEGMENTS = new Set([
  'button',
  'btn',
  'label',
  'title',
  'text',
  'placeholder',
  'hint',
  'tooltip',
  'description',
  'header',
  'message',
  'help',
  'value',
]);

/** `access.oauth-client.allow-all-scopes.title` → "Allow all scopes". */
export function humanizeKey(key: string): string {
  // Quita el prefijo de scope (`identity/tenant.`) y se queda con los segmentos de la clave
  const segments = key
    .split('.')
    .map((segment) => segment.split('/').pop() ?? '')
    .filter((segment) => segment.length > 0);
  const meaningful = [...segments].reverse().find((segment) => !GENERIC_SEGMENTS.has(segment.toLowerCase()));
  const words = (meaningful ?? segments[segments.length - 1] ?? key)
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/[-_]+/g, ' ')
    .trim()
    .toLowerCase();
  return words.length > 0 ? words.charAt(0).toUpperCase() + words.slice(1) : key;
}

/**
 * Qué se pinta cuando falta una traducción: en producción la clave humanizada (nunca una clave con puntos);
 * en desarrollo `⟦clave⟧`, para que se vea, y un aviso en el log la primera vez.
 */
@Injectable()
export class HumanizingMissingHandler implements TranslocoMissingHandler {
  private readonly reported = new Set<string>();

  handle(key: string, data: TranslocoMissingHandlerData): string {
    if (data.prodMode) {
      return humanizeKey(key);
    }
    if (!this.reported.has(key)) {
      this.reported.add(key);
      rootLogger.warn(`i18n: falta la traducción de "${key}" (${data.activeLang})`);
    }
    return `⟦${key}⟧`;
  }
}
